import{_ as t,o as a,c as s,a0 as r}from"./chunks/framework.DB31oXgM.js";const f=JSON.parse('{"title":"ADR 008: Snapshot Retention Strategy (Full Ring Buffer vs Delta Resync)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/008-snapshot-strategy-full-vs-delta.md","filePath":"adr/008-snapshot-strategy-full-vs-delta.md"}'),n={name:"adr/008-snapshot-strategy-full-vs-delta.md"};function o(i,e,l,c,d,u){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-008-snapshot-retention-strategy-full-ring-buffer-vs-delta-resync" tabindex="-1">ADR 008: Snapshot Retention Strategy (Full Ring Buffer vs Delta Resync) <a class="header-anchor" href="#adr-008-snapshot-retention-strategy-full-ring-buffer-vs-delta-resync" aria-label="Permalink to &quot;ADR 008: Snapshot Retention Strategy (Full Ring Buffer vs Delta Resync)&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Rollback resimulation requires instant restoration of past game states when late or mispredicted inputs arrive. During normal gameplay, rollback depth is typically 1 to 8 frames (rarely up to 15 frames). However, upon complete client desynchronization or reconnection, a full state restoration is needed.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Local Ring Buffer (128 ticks)</strong>: The simulation maintains a circular ring buffer of 128 full state snapshots. Every tick snapshot is stored in uncompressed fixed-size memory (~256 bytes per state), allowing $O(1)$ instantaneous clone and restore for rollbacks.</li><li><strong>Periodic Golden Checkpoints</strong>: Every 60 ticks (1 second), an authoritative state checksum is broadcasted for divergence detection.</li><li><strong>Desync / Reconnect Recovery</strong>: If a client diverges beyond the 128-tick window or fails checksum verification, the server transmits a full authoritative snapshot packet followed by current pending inputs to force-resynchronize the client.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Fixed, predictable memory overhead (~32 KB per session).</li><li>Zero compression CPU overhead during high-speed 60Hz tick simulation.</li><li>Guaranteed bit-for-bit state recovery under packet loss or late arrival.</li></ul>',9)])])}const p=t(n,[["render",o]]);export{f as __pageData,p as default};
